div.t-att-class:
{
                                                 'bg-success': record.progress.raw_value == 100,
                                                 'bg-info':    record.progress.raw_value >= 75 and record.progress.raw_value < 100,
                                                 'bg-primary': record.progress.raw_value >= 50 and record.progress.raw_value < 75,
                                                 'bg-warning': record.progress.raw_value < 50
                                             }
